CREATE TABLE guides (id uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, workspace_id uuid NOT NULL, guide_ref text NOT NULL, label text NOT NULL, slice_id uuid NOT NULL, market_definition_id uuid NOT NULL, created_by_actor_id uuid NOT NULL, tombstoned_at timestamptz, created_at timestamptz DEFAULT now() NOT NULL, CONSTRAINT guides_identity CHECK (length(btrim(label)) between 1 and 160 and guide_ref ~ '^guide_[a-z0-9][a-z0-9_.:-]{0,190}$'));
CREATE TABLE guide_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, workspace_id uuid NOT NULL, guide_id uuid NOT NULL, guide_ref text NOT NULL, revision_number integer NOT NULL, revision_hash text NOT NULL, source_revision_id uuid, slice_revision_id uuid NOT NULL, slice_ref text NOT NULL, market_definition_id uuid NOT NULL, free_text text NOT NULL, strict_payload jsonb NOT NULL, schedule_payload jsonb NOT NULL, mode text NOT NULL, interpretation_hash text NOT NULL, created_by_actor_id uuid NOT NULL, created_at timestamptz DEFAULT now() NOT NULL, CONSTRAINT guide_revisions_identity CHECK (revision_number>=1 and revision_hash ~ '^[a-f0-9]{64}$' and slice_ref ~ '^slice_[a-z0-9][a-z0-9_.:-]{0,190}$' and mode in ('observe_analyze','recommend','prepare_human_approval','limited_autonomy') and length(btrim(free_text)) between 1 and 10000 and interpretation_hash ~ '^[a-f0-9]{64}$'));
CREATE TABLE guide_revision_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, workspace_id uuid NOT NULL, guide_revision_id uuid NOT NULL, action text NOT NULL, authority text NOT NULL, created_at timestamptz DEFAULT now() NOT NULL, CONSTRAINT guide_revision_actions_closed CHECK (action in ('status_pause','status_activate','budget_decrease','budget_increase','campaign_rename','adset_rename','ad_rename') and authority in ('none','human_approval','limited_autonomy') and (not (action like '%_rename') or authority = 'human_approval')));
CREATE TABLE guide_revision_budget_refs (id uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, workspace_id uuid NOT NULL, guide_revision_id uuid NOT NULL, budget_ref text NOT NULL, scope_kind text NOT NULL, ordinal integer NOT NULL, created_at timestamptz DEFAULT now() NOT NULL, CONSTRAINT guide_revision_budget_refs_contract CHECK (budget_ref ~ '^limit_[a-z0-9][a-z0-9_.:-]{0,190}$' and scope_kind in ('market','organization_campaign','geo_targeting_platform','campaign_ad_set') and ordinal>=1));
CREATE TABLE guide_interpretation_acceptances (id uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, workspace_id uuid NOT NULL, guide_revision_id uuid NOT NULL, interpretation_hash text NOT NULL, accepted_by_actor_id uuid NOT NULL, accepted_at timestamptz NOT NULL, CONSTRAINT guide_interpretation_acceptances_hash CHECK (interpretation_hash ~ '^[a-f0-9]{64}$'));
CREATE TABLE guide_heads (id uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, workspace_id uuid NOT NULL, guide_id uuid NOT NULL, latest_revision_id uuid, current_active_revision_id uuid, version integer DEFAULT 0 NOT NULL, updated_at timestamptz DEFAULT now() NOT NULL, CONSTRAINT guide_heads_version_nonnegative CHECK(version>=0));
CREATE TABLE guide_lifecycle_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, workspace_id uuid NOT NULL, guide_id uuid NOT NULL, guide_revision_id uuid NOT NULL, event_key text NOT NULL, event_type text NOT NULL, actor_id uuid NOT NULL, occurred_at timestamptz NOT NULL, payload jsonb NOT NULL, CONSTRAINT guide_lifecycle_events_type CHECK(event_type in ('draft_created','interpretation_accepted','activated','superseded','paused','archived') and event_key ~ '^guide_event_[a-f0-9]{64}$'));
CREATE TABLE guide_activation_outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, workspace_id uuid NOT NULL, guide_id uuid NOT NULL, guide_revision_id uuid NOT NULL, activation_key text NOT NULL, created_at timestamptz NOT NULL, CONSTRAINT guide_activation_outbox_key CHECK(activation_key ~ '^guide_activation_[a-f0-9]{64}$'));

CREATE UNIQUE INDEX guides_workspace_row_unique ON guides(workspace_id,id); CREATE UNIQUE INDEX guides_workspace_ref_unique ON guides(workspace_id,guide_ref); CREATE UNIQUE INDEX guides_workspace_identity_market_unique ON guides(workspace_id,id,guide_ref,market_definition_id); CREATE UNIQUE INDEX guides_workspace_slice_market_unique ON guides(workspace_id,id,slice_id,market_definition_id); CREATE INDEX guides_workspace_live_idx ON guides(workspace_id,tombstoned_at,created_at);
CREATE UNIQUE INDEX guide_revisions_workspace_row_unique ON guide_revisions(workspace_id,id); CREATE UNIQUE INDEX guide_revisions_workspace_guide_row_unique ON guide_revisions(workspace_id,id,guide_id); CREATE UNIQUE INDEX guide_revisions_workspace_guide_number_unique ON guide_revisions(workspace_id,guide_id,revision_number); CREATE UNIQUE INDEX guide_revisions_workspace_hash_unique ON guide_revisions(workspace_id,revision_hash); CREATE INDEX guide_revisions_workspace_guide_idx ON guide_revisions(workspace_id,guide_id,revision_number);
CREATE UNIQUE INDEX guide_revision_actions_workspace_unique ON guide_revision_actions(workspace_id,guide_revision_id,action); CREATE INDEX guide_revision_actions_workspace_revision_idx ON guide_revision_actions(workspace_id,guide_revision_id); CREATE UNIQUE INDEX guide_revision_budget_refs_workspace_unique ON guide_revision_budget_refs(workspace_id,guide_revision_id,budget_ref); CREATE UNIQUE INDEX guide_revision_budget_refs_ordinal_unique ON guide_revision_budget_refs(workspace_id,guide_revision_id,ordinal); CREATE INDEX guide_revision_budget_refs_workspace_revision_idx ON guide_revision_budget_refs(workspace_id,guide_revision_id);
CREATE UNIQUE INDEX guide_interpretation_acceptances_exact_unique ON guide_interpretation_acceptances(workspace_id,guide_revision_id,interpretation_hash); CREATE INDEX guide_interpretation_acceptances_workspace_revision_idx ON guide_interpretation_acceptances(workspace_id,guide_revision_id); CREATE UNIQUE INDEX guide_heads_workspace_guide_unique ON guide_heads(workspace_id,guide_id); CREATE UNIQUE INDEX guide_lifecycle_events_workspace_key_unique ON guide_lifecycle_events(workspace_id,event_key); CREATE INDEX guide_lifecycle_events_workspace_guide_idx ON guide_lifecycle_events(workspace_id,guide_id,occurred_at); CREATE UNIQUE INDEX guide_activation_outbox_key_unique ON guide_activation_outbox(workspace_id,activation_key); CREATE INDEX guide_activation_outbox_workspace_revision_idx ON guide_activation_outbox(workspace_id,guide_revision_id,created_at);

ALTER TABLE guides ADD CONSTRAINT guides_workspace_fk FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE cascade; ALTER TABLE guides ADD CONSTRAINT guides_slice_market_scope_fk FOREIGN KEY(workspace_id,slice_id,market_definition_id) REFERENCES slices(workspace_id,id,market_definition_id) ON DELETE restrict; ALTER TABLE guides ADD CONSTRAINT guides_creator_scope_fk FOREIGN KEY(workspace_id,created_by_actor_id) REFERENCES memberships(workspace_id,user_id) ON DELETE restrict;
ALTER TABLE guide_revisions ADD CONSTRAINT guide_revisions_workspace_fk FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE cascade; ALTER TABLE guide_revisions ADD CONSTRAINT guide_revisions_guide_market_scope_fk FOREIGN KEY(workspace_id,guide_id,guide_ref,market_definition_id) REFERENCES guides(workspace_id,id,guide_ref,market_definition_id) ON DELETE restrict; ALTER TABLE guide_revisions ADD CONSTRAINT guide_revisions_slice_revision_scope_fk FOREIGN KEY(workspace_id,slice_revision_id) REFERENCES slice_revisions(workspace_id,id) ON DELETE restrict; ALTER TABLE guide_revisions ADD CONSTRAINT guide_revisions_source_scope_fk FOREIGN KEY(workspace_id,source_revision_id,guide_id) REFERENCES guide_revisions(workspace_id,id,guide_id) ON DELETE restrict; ALTER TABLE guide_revisions ADD CONSTRAINT guide_revisions_creator_scope_fk FOREIGN KEY(workspace_id,created_by_actor_id) REFERENCES memberships(workspace_id,user_id) ON DELETE restrict;
ALTER TABLE guide_revision_actions ADD CONSTRAINT guide_revision_actions_revision_scope_fk FOREIGN KEY(workspace_id,guide_revision_id) REFERENCES guide_revisions(workspace_id,id) ON DELETE cascade; ALTER TABLE guide_revision_budget_refs ADD CONSTRAINT guide_revision_budget_refs_revision_scope_fk FOREIGN KEY(workspace_id,guide_revision_id) REFERENCES guide_revisions(workspace_id,id) ON DELETE cascade; ALTER TABLE guide_interpretation_acceptances ADD CONSTRAINT guide_interpretation_acceptances_revision_scope_fk FOREIGN KEY(workspace_id,guide_revision_id) REFERENCES guide_revisions(workspace_id,id) ON DELETE restrict; ALTER TABLE guide_interpretation_acceptances ADD CONSTRAINT guide_interpretation_acceptances_actor_scope_fk FOREIGN KEY(workspace_id,accepted_by_actor_id) REFERENCES memberships(workspace_id,user_id) ON DELETE restrict;
ALTER TABLE guide_heads ADD CONSTRAINT guide_heads_workspace_fk FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE cascade; ALTER TABLE guide_heads ADD CONSTRAINT guide_heads_guide_scope_fk FOREIGN KEY(workspace_id,guide_id) REFERENCES guides(workspace_id,id) ON DELETE cascade; ALTER TABLE guide_heads ADD CONSTRAINT guide_heads_latest_revision_scope_fk FOREIGN KEY(workspace_id,latest_revision_id,guide_id) REFERENCES guide_revisions(workspace_id,id,guide_id) ON DELETE restrict; ALTER TABLE guide_heads ADD CONSTRAINT guide_heads_active_revision_scope_fk FOREIGN KEY(workspace_id,current_active_revision_id,guide_id) REFERENCES guide_revisions(workspace_id,id,guide_id) ON DELETE restrict;
ALTER TABLE guide_lifecycle_events ADD CONSTRAINT guide_lifecycle_events_guide_scope_fk FOREIGN KEY(workspace_id,guide_id) REFERENCES guides(workspace_id,id) ON DELETE restrict; ALTER TABLE guide_lifecycle_events ADD CONSTRAINT guide_lifecycle_events_revision_scope_fk FOREIGN KEY(workspace_id,guide_revision_id,guide_id) REFERENCES guide_revisions(workspace_id,id,guide_id) ON DELETE restrict; ALTER TABLE guide_lifecycle_events ADD CONSTRAINT guide_lifecycle_events_actor_scope_fk FOREIGN KEY(workspace_id,actor_id) REFERENCES memberships(workspace_id,user_id) ON DELETE restrict; ALTER TABLE guide_activation_outbox ADD CONSTRAINT guide_activation_outbox_guide_scope_fk FOREIGN KEY(workspace_id,guide_id) REFERENCES guides(workspace_id,id) ON DELETE restrict; ALTER TABLE guide_activation_outbox ADD CONSTRAINT guide_activation_outbox_revision_scope_fk FOREIGN KEY(workspace_id,guide_revision_id,guide_id) REFERENCES guide_revisions(workspace_id,id,guide_id) ON DELETE restrict;

ALTER TABLE guides ENABLE ROW LEVEL SECURITY; ALTER TABLE guides FORCE ROW LEVEL SECURITY; ALTER TABLE guide_revisions ENABLE ROW LEVEL SECURITY; ALTER TABLE guide_revisions FORCE ROW LEVEL SECURITY; ALTER TABLE guide_revision_actions ENABLE ROW LEVEL SECURITY; ALTER TABLE guide_revision_actions FORCE ROW LEVEL SECURITY; ALTER TABLE guide_revision_budget_refs ENABLE ROW LEVEL SECURITY; ALTER TABLE guide_revision_budget_refs FORCE ROW LEVEL SECURITY; ALTER TABLE guide_interpretation_acceptances ENABLE ROW LEVEL SECURITY; ALTER TABLE guide_interpretation_acceptances FORCE ROW LEVEL SECURITY; ALTER TABLE guide_heads ENABLE ROW LEVEL SECURITY; ALTER TABLE guide_heads FORCE ROW LEVEL SECURITY; ALTER TABLE guide_lifecycle_events ENABLE ROW LEVEL SECURITY; ALTER TABLE guide_lifecycle_events FORCE ROW LEVEL SECURITY; ALTER TABLE guide_activation_outbox ENABLE ROW LEVEL SECURITY; ALTER TABLE guide_activation_outbox FORCE ROW LEVEL SECURITY;
REVOKE ALL PRIVILEGES ON TABLE guides,guide_revisions,guide_revision_actions,guide_revision_budget_refs,guide_interpretation_acceptances,guide_heads,guide_lifecycle_events,guide_activation_outbox FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.guide_revision_guard() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF TG_OP<>'INSERT' THEN IF TG_OP='DELETE' AND EXISTS(SELECT 1 FROM workspaces WHERE id=OLD.workspace_id AND lifecycle_state='tombstoning') THEN RETURN OLD; END IF; RAISE EXCEPTION 'guide revisions are append-only'; END IF; IF NOT EXISTS(SELECT 1 FROM guides g JOIN slice_revisions s ON s.workspace_id=g.workspace_id AND s.id=NEW.slice_revision_id WHERE g.workspace_id=NEW.workspace_id AND g.id=NEW.guide_id AND g.guide_ref=NEW.guide_ref AND g.market_definition_id=NEW.market_definition_id AND g.tombstoned_at IS NULL AND s.slice_id=g.slice_id AND s.slice_ref=NEW.slice_ref AND s.market_definition_id=g.market_definition_id AND s.lifecycle='published') THEN RAISE EXCEPTION 'guide revision must bind one published same-market slice revision'; END IF; IF NEW.revision_number=1 AND NEW.source_revision_id IS NULL AND NOT EXISTS(SELECT 1 FROM guide_revisions r WHERE r.workspace_id=NEW.workspace_id AND r.guide_id=NEW.guide_id) THEN RETURN NEW; END IF; IF NEW.source_revision_id IS NOT NULL AND EXISTS(SELECT 1 FROM guide_revisions p WHERE p.workspace_id=NEW.workspace_id AND p.id=NEW.source_revision_id AND p.guide_id=NEW.guide_id AND p.revision_number=NEW.revision_number-1) THEN RETURN NEW; END IF; RAISE EXCEPTION 'guide revisions must be exact append-only successors'; END; $$;
CREATE OR REPLACE FUNCTION public.guide_child_append_only_guard() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN RETURN NEW; END IF; IF TG_OP='DELETE' AND EXISTS(SELECT 1 FROM workspaces WHERE id=OLD.workspace_id AND lifecycle_state='tombstoning') THEN RETURN OLD; END IF; RAISE EXCEPTION 'guide evidence is append-only'; END; $$;
CREATE OR REPLACE FUNCTION public.guide_head_guard() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN IF NEW.version=0 AND NEW.current_active_revision_id IS NULL AND NEW.latest_revision_id IS NOT NULL AND EXISTS(SELECT 1 FROM guide_revisions r WHERE r.workspace_id=NEW.workspace_id AND r.id=NEW.latest_revision_id AND r.guide_id=NEW.guide_id) THEN RETURN NEW; END IF; RAISE EXCEPTION 'guide head must start at its first immutable revision'; END IF; IF NEW.workspace_id<>OLD.workspace_id OR NEW.guide_id<>OLD.guide_id OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'guide head requires monotonic OCC version'; END IF; IF NEW.latest_revision_id IS DISTINCT FROM OLD.latest_revision_id AND NEW.current_active_revision_id IS NOT DISTINCT FROM OLD.current_active_revision_id AND NEW.latest_revision_id IS NOT NULL AND EXISTS(SELECT 1 FROM guide_revisions n JOIN guide_revisions p ON p.workspace_id=n.workspace_id AND p.id=n.source_revision_id WHERE n.workspace_id=NEW.workspace_id AND n.id=NEW.latest_revision_id AND n.guide_id=NEW.guide_id AND p.id=OLD.latest_revision_id AND n.revision_number=p.revision_number+1) THEN RETURN NEW; END IF; IF NEW.latest_revision_id IS NOT DISTINCT FROM OLD.latest_revision_id AND NEW.current_active_revision_id=NEW.latest_revision_id AND EXISTS(SELECT 1 FROM guide_revisions r WHERE r.workspace_id=NEW.workspace_id AND r.id=NEW.latest_revision_id AND r.guide_id=NEW.guide_id AND EXISTS(SELECT 1 FROM guide_interpretation_acceptances a WHERE a.workspace_id=r.workspace_id AND a.guide_revision_id=r.id AND a.interpretation_hash=r.interpretation_hash)) THEN RETURN NEW; END IF; IF NEW.latest_revision_id IS NOT DISTINCT FROM OLD.latest_revision_id AND NEW.current_active_revision_id IS NULL AND OLD.current_active_revision_id IS NOT NULL THEN RETURN NEW; END IF; RAISE EXCEPTION 'guide head only permits exact next draft, accepted latest activation, or pause'; END; $$;
CREATE OR REPLACE FUNCTION public.guide_identity_guard() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN RETURN NEW; END IF; IF TG_OP='DELETE' AND EXISTS(SELECT 1 FROM workspaces WHERE id=OLD.workspace_id AND lifecycle_state='tombstoning') THEN RETURN OLD; END IF; IF TG_OP='UPDATE' AND OLD.tombstoned_at IS NULL AND NEW.tombstoned_at IS NOT NULL AND NEW.id=OLD.id AND NEW.workspace_id=OLD.workspace_id AND NEW.guide_ref=OLD.guide_ref AND NEW.label=OLD.label AND NEW.slice_id=OLD.slice_id AND NEW.market_definition_id=OLD.market_definition_id AND NEW.created_by_actor_id=OLD.created_by_actor_id AND NEW.created_at=OLD.created_at AND EXISTS(SELECT 1 FROM guide_heads h WHERE h.workspace_id=NEW.workspace_id AND h.guide_id=NEW.id AND h.current_active_revision_id IS NULL) THEN RETURN NEW; END IF; RAISE EXCEPTION 'guides are immutable; archive requires a paused guide'; END; $$;
CREATE TRIGGER guides_guard BEFORE INSERT OR UPDATE OR DELETE ON guides FOR EACH ROW EXECUTE FUNCTION public.guide_identity_guard(); CREATE TRIGGER guide_revisions_append_only BEFORE INSERT OR UPDATE OR DELETE ON guide_revisions FOR EACH ROW EXECUTE FUNCTION public.guide_revision_guard(); CREATE TRIGGER guide_revision_actions_append_only BEFORE INSERT OR UPDATE OR DELETE ON guide_revision_actions FOR EACH ROW EXECUTE FUNCTION public.guide_child_append_only_guard(); CREATE TRIGGER guide_revision_budget_refs_append_only BEFORE INSERT OR UPDATE OR DELETE ON guide_revision_budget_refs FOR EACH ROW EXECUTE FUNCTION public.guide_child_append_only_guard(); CREATE TRIGGER guide_interpretation_acceptances_append_only BEFORE INSERT OR UPDATE OR DELETE ON guide_interpretation_acceptances FOR EACH ROW EXECUTE FUNCTION public.guide_child_append_only_guard(); CREATE TRIGGER guide_lifecycle_events_append_only BEFORE INSERT OR UPDATE OR DELETE ON guide_lifecycle_events FOR EACH ROW EXECUTE FUNCTION public.guide_child_append_only_guard(); CREATE TRIGGER guide_activation_outbox_append_only BEFORE INSERT OR UPDATE OR DELETE ON guide_activation_outbox FOR EACH ROW EXECUTE FUNCTION public.guide_child_append_only_guard(); CREATE TRIGGER guide_heads_guard BEFORE INSERT OR UPDATE ON guide_heads FOR EACH ROW EXECUTE FUNCTION public.guide_head_guard();
REVOKE ALL PRIVILEGES ON FUNCTION public.guide_revision_guard(),public.guide_child_append_only_guard(),public.guide_head_guard(),public.guide_identity_guard() FROM PUBLIC, anon, authenticated, service_role;
